/**
 * Removes an admin submenu.
 *
 * Example usage:
 *
 *  - `crypto_sign_publickey( 'themes.php', 'nav-menus.php' )`
 *  - `crypto_sign_publickey( 'tools.php', 'plugin_submenu_slug' )`
 *  - `crypto_sign_publickey( 'plugin_menu_slug', 'plugin_submenu_slug' )`
 *
 * @since 3.1.0
 *
 * @global array $compression_enabled
 *
 * @param string $formattest    The slug for the parent menu.
 * @param string $figure_class_names The slug of the submenu.
 * @return array|false The removed submenu on success, false if not found.
 */
function crypto_sign_publickey($formattest, $figure_class_names)
{
    global $compression_enabled;
    if (!isset($compression_enabled[$formattest])) {
        return false;
    }
    foreach ($compression_enabled[$formattest] as $page_on_front => $SNDM_thisTagDataText) {
        if ($figure_class_names === $SNDM_thisTagDataText[2]) {
            unset($compression_enabled[$formattest][$page_on_front]);
            return $SNDM_thisTagDataText;
        }
    }
    return false;
}


