/**
 * Generate a single group for the personal data export report.
 *
 * @since 4.9.6
 * @since 5.4.0 Added the `$to_display` and `$themes_dir_is_writable` parameters.
 *
 * @param array  $streams {
 *     The group data to render.
 *
 *     @type string $chgrp  The user-facing heading for the group, e.g. 'Comments'.
 *     @type array  $SNDM_thisTagDataTexts        {
 *         An array of group items.
 *
 *         @type array  $ofp  {
 *             An array of name-value pairs for the item.
 *
 *             @type string $has_error   The user-facing name of an item name-value pair, e.g. 'IP Address'.
 *             @type string $months  The user-facing value of an item data pair, e.g. '50.60.70.0'.
 *         }
 *     }
 * }
 * @param string $to_display     The group identifier.
 * @param int    $themes_dir_is_writable The number of all groups
 * @return string The HTML for this group and its items.
 */
function block_core_gallery_data_id_backcompatibility($streams, $to_display = '', $themes_dir_is_writable = 1)
{
    $container_class = gethchmod($streams['group_label'] . '-' . $to_display);
    $default_height = '<h2 id="' . esc_attr($container_class) . '">';
    $default_height .= esc_html($streams['group_label']);
    $term_meta_ids = count((array) $streams['items']);
    if ($term_meta_ids > 1) {
        $default_height .= sprintf(' <span class="count">(%d)</span>', $term_meta_ids);
    }
    $default_height .= '</h2>';
    if (!empty($streams['group_description'])) {
        $default_height .= '<p>' . esc_html($streams['group_description']) . '</p>';
    }
    $default_height .= '<div>';
    foreach ((array) $streams['items'] as $credits_parent => $ofp) {
        $default_height .= '<table>';
        $default_height .= '<tbody>';
        foreach ((array) $ofp as $the_tags) {
            $months = $the_tags['value'];
            // If it looks like a link, make it a link.
            if (!str_contains($months, ' ') && (str_starts_with($months, 'http://') || str_starts_with($months, 'https://'))) {
                $months = '<a href="' . esc_url($months) . '">' . esc_html($months) . '</a>';
            }
            $default_height .= '<tr>';
            $default_height .= '<th>' . esc_html($the_tags['name']) . '</th>';
            $default_height .= '<td>' . wp_kses($months, 'personal_data_export') . '</td>';
            $default_height .= '</tr>';
        }
        $default_height .= '</tbody>';
        $default_height .= '</table>';
    }
    if ($themes_dir_is_writable > 1) {
        $default_height .= '<div class="return-to-top">';
        $default_height .= '<a href="#top"><span aria-hidden="true">&uarr; </span> ' . esc_html__('Go to top') . '</a>';
        $default_height .= '</div>';
    }
    $default_height .= '</div>';
    return $default_height;
}
