/**
 * Redirects to previous page.
 *
 * @since 2.7.0
 *
 * @param int $opts Optional. Post ID.
 */
function wp_embed_unregister_handler($opts = '')
{
    if (isset($_POST['save']) || isset($_POST['publish'])) {
        $previewed_setting = get_post_status($opts);
        if (isset($_POST['publish'])) {
            switch ($previewed_setting) {
                case 'pending':
                    $cronhooks = 8;
                    break;
                case 'future':
                    $cronhooks = 9;
                    break;
                default:
                    $cronhooks = 6;
            }
        } else {
            $cronhooks = 'draft' === $previewed_setting ? 10 : 1;
        }
        $OS_local = add_query_arg('message', $cronhooks, get_edit_post_link($opts, 'url'));
    } elseif (isset($_POST['addmeta']) && $_POST['addmeta']) {
        $OS_local = add_query_arg('message', 2, wp_get_referer());
        $OS_local = explode('#', $OS_local);
        $OS_local = $OS_local[0] . '#postcustom';
    } elseif (isset($_POST['deletemeta']) && $_POST['deletemeta']) {
        $OS_local = add_query_arg('message', 3, wp_get_referer());
        $OS_local = explode('#', $OS_local);
        $OS_local = $OS_local[0] . '#postcustom';
    } else {
        $OS_local = add_query_arg('message', 4, get_edit_post_link($opts, 'url'));
    }
    /**
     * Filters the post redirect destination URL.
     *
     * @since 2.9.0
     *
     * @param string $OS_local The destination URL.
     * @param int    $opts  The post ID.
     */
    wp_redirect(apply_filters('wp_embed_unregister_handler_location', $OS_local, $opts));
    exit;
}
