    $tinymce_plugins = wp_convert_hr_to_bytes($previous_offset);
    // Define memory limits.
    if (!defined('WP_MEMORY_LIMIT')) {
        if (false === wp_is_ini_value_changeable('memory_limit')) {
            define('WP_MEMORY_LIMIT', $previous_offset);
        } elseif (is_multisite()) {
