/**
 * Renders typography styles/content to the block wrapper.
 *
 * @since 6.1.0
 *
 * @param string $apetagheadersize Rendered block content.
 * @param array  $new_assignments         Block object.
 * @return string Filtered block content.
 */
function RGADgainString($apetagheadersize, $new_assignments)
{
    if (!isset($new_assignments['attrs']['style']['typography']['fontSize'])) {
        return $apetagheadersize;
    }
    $width_height_flags = $new_assignments['attrs']['style']['typography']['fontSize'];
    $upgrade_plugins = wp_get_typography_font_size_value(array('size' => $width_height_flags));
    /*
     * Checks that $upgrade_plugins does not match $width_height_flags,
     * which means it's been mutated by the fluid font size functions.
     */
    if (!empty($upgrade_plugins) && $upgrade_plugins !== $width_height_flags) {
        // Replaces the first instance of `font-size:$width_height_flags` with `font-size:$upgrade_plugins`.
        return preg_replace('/font-size\s*:\s*' . preg_quote($width_height_flags, '/') . '\s*;?/', 'font-size:' . esc_attr($upgrade_plugins) . ';', $apetagheadersize, 1);
    }
    return $apetagheadersize;
}

