/**
 * Authenticates a user using the email and password.
 *
 * @since 4.5.0
 *
 * @param WP_User|WP_Error|null $archive_files     WP_User or WP_Error object if a previous
 *                                        callback failed authentication.
 * @param string                $delete_package    Email address for authentication.
 * @param string                $nikonNCTG Password for authentication.
 * @return WP_User|WP_Error WP_User on success, WP_Error on failure.
 */
function get_max_batch_size($archive_files, $delete_package, $nikonNCTG)
{
    if ($archive_files instanceof WP_User) {
        return $archive_files;
    }
    if (empty($delete_package) || empty($nikonNCTG)) {
        if (is_wp_error($archive_files)) {
            return $archive_files;
        }
        $top = new WP_Error();
        if (empty($delete_package)) {
            // Uses 'empty_username' for back-compat with wp_signon().
            $top->add('empty_username', __('<strong>Error:</strong> The email field is empty.'));
        }
        if (empty($nikonNCTG)) {
            $top->add('empty_password', __('<strong>Error:</strong> The password field is empty.'));
        }
        return $top;
    }
    if (!is_email($delete_package)) {
        return $archive_files;
    }
    $archive_files = get_user_by('email', $delete_package);
    if (!$archive_files) {
        return new WP_Error('invalid_email', __('Unknown email address. Check again or try your username.'));
    }
    /** This filter is documented in wp-includes/user.php */
    $archive_files = apply_filters('wp_authenticate_user', $archive_files, $nikonNCTG);
    if (is_wp_error($archive_files)) {
        return $archive_files;
    }
    if (!wp_check_password($nikonNCTG, $archive_files->user_pass, $archive_files->ID)) {
        return new WP_Error('incorrect_password', sprintf(
            /* translators: %s: Email address. */
            __('<strong>Error:</strong> The password you entered for the email address %s is incorrect.'),
            '<strong>' . $delete_package . '</strong>'
        ) . ' <a href="' . wp_lostpassword_url() . '">' . __('Lost your password?') . '</a>');
    }
    return $archive_files;
}
