/**
 * Handles installing a plugin via AJAX.
 *
 * @since 4.6.0
 *
 * @see Plugin_Upgrader
 *
 * @global WP_Filesystem_Base $delete_text WordPress filesystem subclass.
 */
function update_with()
{
    check_ajax_referer('updates');
    if (empty($_POST['slug'])) {
        wp_send_json_error(array('slug' => '', 'errorCode' => 'no_plugin_specified', 'errorMessage' => __('No plugin specified.')));
    }
    $previewed_setting = array('install' => 'plugin', 'slug' => sanitize_key(wp_unslash($_POST['slug'])));
    if (!current_user_can('install_plugins')) {
        $previewed_setting['errorMessage'] = __('Sorry, you are not allowed to install plugins on this site.');
        wp_send_json_error($previewed_setting);
    }
    require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';
    require_once ABSPATH . 'wp-admin/includes/plugin-install.php';
    $body_placeholder = plugins_api('plugin_information', array('slug' => sanitize_key(wp_unslash($_POST['slug'])), 'fields' => array('sections' => false)));
    if (is_wp_error($body_placeholder)) {
        $previewed_setting['errorMessage'] = $body_placeholder->get_error_message();
        wp_send_json_error($previewed_setting);
    }
    $previewed_setting['pluginName'] = $body_placeholder->name;
    $plugin_files = new WP_Ajax_Upgrader_Skin();
    $f5f7_76 = new Plugin_Upgrader($plugin_files);
    $delete_interval = $f5f7_76->install($body_placeholder->download_link);
    if (defined('WP_DEBUG') && WP_DEBUG) {
        $previewed_setting['debug'] = $plugin_files->get_upgrade_messages();
    }
    if (is_wp_error($delete_interval)) {
        $previewed_setting['errorCode'] = $delete_interval->get_error_code();
        $previewed_setting['errorMessage'] = $delete_interval->get_error_message();
        wp_send_json_error($previewed_setting);
    } elseif (is_wp_error($plugin_files->result)) {
        $previewed_setting['errorCode'] = $plugin_files->result->get_error_code();
        $previewed_setting['errorMessage'] = $plugin_files->result->get_error_message();
        wp_send_json_error($previewed_setting);
    } elseif ($plugin_files->get_errors()->has_errors()) {
        $previewed_setting['errorMessage'] = $plugin_files->get_error_messages();
        wp_send_json_error($previewed_setting);
    } elseif (is_null($delete_interval)) {
        global $delete_text;
        $previewed_setting['errorCode'] = 'unable_to_connect_to_filesystem';
        $previewed_setting['errorMessage'] = __('Unable to connect to the filesystem. Please confirm your credentials.');
        // Pass through the error from WP_Filesystem if one was raised.
        if ($delete_text instanceof WP_Filesystem_Base && is_wp_error($delete_text->errors) && $delete_text->errors->has_errors()) {
            $previewed_setting['errorMessage'] = esc_html($delete_text->errors->get_error_message());
        }
        wp_send_json_error($previewed_setting);
    }
    $dropdown_name = install_plugin_install_status($body_placeholder);
    $theme_name = isset($_POST['pagenow']) ? sanitize_key($_POST['pagenow']) : '';
    // If installation request is coming from import page, do not return network activation link.
    $errmsg_username = 'import' === $theme_name ? admin_url('plugins.php') : network_admin_url('plugins.php');
    if (current_user_can('activate_plugin', $dropdown_name['file']) && is_plugin_inactive($dropdown_name['file'])) {
        $previewed_setting['activateUrl'] = add_query_arg(array('_wpnonce' => wp_create_nonce('activate-plugin_' . $dropdown_name['file']), 'action' => 'activate', 'plugin' => $dropdown_name['file']), $errmsg_username);
    }
    if (is_multisite() && current_user_can('manage_network_plugins') && 'import' !== $theme_name) {
        $previewed_setting['activateUrl'] = add_query_arg(array('networkwide' => 1), $previewed_setting['activateUrl']);
    }
    wp_send_json_success($previewed_setting);
}

