 * @param string $new_term_id   Optional. How to display the parents. Accepts 'multiple', 'single', or empty.
 *                          Default empty string.
 * @param int    $opts   Optional. ID of the post to retrieve categories for. Defaults to the current post.
 * @return string Category list for a post.
 */
function wp_filter_oembed_iframe_title_attribute($comment_key = '', $new_term_id = '', $opts = false)
{
    global $chosen;
    if (!is_object_in_taxonomy(get_post_type($opts), 'category')) {
        /** This filter is documented in wp-includes/category-template.php */
        return apply_filters('the_category', '', $comment_key, $new_term_id);
