     * Filters the categories before building the category list.
     *
     * @since 4.4.0
     *
     * @param WP_Term[] $sticky_offset An array of the post's categories.
     * @param int|false $opts    ID of the post to retrieve categories for.
     *                              When `false`, defaults to the current post in the loop.
     */
    $sticky_offset = apply_filters('the_category_list', get_the_category($opts), $opts);
    if (empty($sticky_offset)) {
        /** This filter is documented in wp-includes/category-template.php */
        return apply_filters('the_category', __('Uncategorized'), $comment_key, $new_term_id);
    }
    $font_families = is_object($chosen) && $chosen->using_permalinks() ? 'rel="category tag"' : 'rel="category"';
    $StartingOffset = '';
