        foreach ($sticky_offset as $abbr_attr) {
            $StartingOffset .= "\n\t<li>";
            switch (strtolower($new_term_id)) {
                case 'multiple':
                    if ($abbr_attr->parent) {
                        $StartingOffset .= get_category_parents($abbr_attr->parent, true, $comment_key);
                    }
                    $StartingOffset .= '<a href="' . esc_url(get_category_link($abbr_attr->term_id)) . '" ' . $font_families . '>' . $abbr_attr->name . '</a></li>';
                    break;
                case 'single':
                    $StartingOffset .= '<a href="' . esc_url(get_category_link($abbr_attr->term_id)) . '"  ' . $font_families . '>';
                    if ($abbr_attr->parent) {
                        $StartingOffset .= get_category_parents($abbr_attr->parent, false, $comment_key);
                    }
                    $StartingOffset .= $abbr_attr->name . '</a></li>';
                    break;
                case '':
                default:
                    $StartingOffset .= '<a href="' . esc_url(get_category_link($abbr_attr->term_id)) . '" ' . $font_families . '>' . $abbr_attr->name . '</a></li>';
            }
        }
        $StartingOffset .= '</ul>';
    } else {
        $page_on_front = 0;
        foreach ($sticky_offset as $abbr_attr) {
