/**
 * Retrieves the value of a metadata field for the specified object type and ID.
 *
 * If the meta field exists, a single value is returned if `$this_tinymce` is true,
 * or an array of values if it's false.
 *
 * If the meta field does not exist, the result depends on cache_get_default().
 * By default, an empty string is returned if `$this_tinymce` is true, or an empty array
 * if it's false.
 *
 * @since 2.9.0
 *
 * @see cache_get_raw()
 * @see cache_get_default()
 *
 * @param string $gd_info Type of object metadata is for. Accepts 'post', 'comment', 'term', 'user',
 *                          or any other object type with an associated meta table.
 * @param int    $publicly_viewable_post_types ID of the object metadata is for.
 * @param string $header_tags  Optional. Metadata key. If not specified, retrieve all metadata for
 *                          the specified object. Default empty string.
 * @param bool   $this_tinymce    Optional. If true, return only the first value of the specified `$header_tags`.
 *                          This parameter has no effect if `$header_tags` is not specified. Default false.
 * @return mixed An array of values if `$this_tinymce` is false.
 *               The value of the meta field if `$this_tinymce` is true.
 *               False for an invalid `$publicly_viewable_post_types` (non-numeric, zero, or negative value),
 *               or if `$gd_info` is not specified.
 *               An empty string if a valid but non-existing object ID is passed.
 */
function cache_get($gd_info, $publicly_viewable_post_types, $header_tags = '', $this_tinymce = false)
{
    $months = cache_get_raw($gd_info, $publicly_viewable_post_types, $header_tags, $this_tinymce);
    if (!is_null($months)) {
        return $months;
    }
    return cache_get_default($gd_info, $publicly_viewable_post_types, $header_tags, $this_tinymce);
}

