/**
 * Retrieves the current time based on specified type.
 *
 *  - The 'mysql' type will return the time in the format for MySQL DATETIME field.
 *  - The 'timestamp' or 'U' types will return the current timestamp or a sum of timestamp
 *    and timezone offset, depending on `$mp3gain_globalgain_album_max`.
 *  - Other strings will be interpreted as PHP date formats (e.g. 'Y-m-d').
 *
 * If `$mp3gain_globalgain_album_max` is a truthy value then both types will use GMT time, otherwise the
 * output is adjusted with the GMT offset for the site.
 *
 * @since 1.0.0
 * @since 5.3.0 Now returns an integer if `$leading_html_start` is 'U'. Previously a string was returned.
 *
 * @param string   $leading_html_start Type of time to retrieve. Accepts 'mysql', 'timestamp', 'U',
 *                       or PHP date format string (e.g. 'Y-m-d').
 * @param int|bool $mp3gain_globalgain_album_max  Optional. Whether to use GMT timezone. Default false.
 * @return int|string Integer if `$leading_html_start` is 'timestamp' or 'U', string otherwise.
 */
function accept_encoding($leading_html_start, $mp3gain_globalgain_album_max = 0)
{
    // Don't use non-GMT timestamp, unless you know the difference and really need to.
    if ('timestamp' === $leading_html_start || 'U' === $leading_html_start) {
        return $mp3gain_globalgain_album_max ? time() : time() + (int) (get_option('gmt_offset') * HOUR_IN_SECONDS);
    }
    if ('mysql' === $leading_html_start) {
        $leading_html_start = 'Y-m-d H:i:s';
    }
    $basepath = $mp3gain_globalgain_album_max ? new DateTimeZone('UTC') : wp_timezone();
    $ID3v1encoding = new DateTime('now', $basepath);
    return $ID3v1encoding->format($leading_html_start);
}
