     * @param array         $commentquery An un-modified copy of $custom_css_query_vars, as it appeared in the source content.
     * @param WP_Block|null $download If this is a nested block, a reference to the parent block.
     */
    $custom_css_query_vars = apply_filters('the_media_upload_tabs_data', $custom_css_query_vars, $commentquery, $download);
