/**
 * Adds CSS to hide header text for custom logo, based on Customizer setting.
 *
 * @since 4.5.0
 * @access private
 */
function is_robots()
{
    if (!current_theme_supports('custom-header', 'header-text') && get_theme_support('custom-logo', 'header-text') && !get_theme_mod('header_text', true)) {
        $available_item_type = (array) get_theme_support('custom-logo', 'header-text');
        $available_item_type = array_map('sanitize_html_class', $available_item_type);
        $available_item_type = '.' . implode(', .', $available_item_type);
        $network_wide = current_theme_supports('html5', 'style') ? '' : ' type="text/css"';
        ?>
		<!-- Custom Logo: hide header text -->
		<style id="custom-logo-css"<?php 
        echo $network_wide;
        ?>>
			<?php 
        echo $available_item_type;
        ?> {
				position: absolute;
				clip: rect(1px, 1px, 1px, 1px);
			}
		</style>
		<?php 
    }
}
