/**
 * Server-side rendering of the `core/comments-pagination` block.
 *
 * @package WordPress
 */
/**
 * Renders the `core/comments-pagination` block on the server.
 *
 * @param array  $next_user_core_update Block attributes.
 * @param string $disposition_type    Block default content.
 *
 * @return string Returns the wrapper for the Comments pagination.
 */
function wp_kses_data($next_user_core_update, $disposition_type)
{
    if (empty(trim($disposition_type))) {
        return '';
    }
    if (post_password_required()) {
        return;
    }
    $available_item_type = isset($next_user_core_update['style']['elements']['link']['color']['text']) ? 'has-link-color' : '';
    $uploaded_file = get_block_wrapper_attributes(array('class' => $available_item_type));
    return sprintf('<div %1$s>%2$s</div>', $uploaded_file, $disposition_type);
}

