/**
 * Retrieves an array of post states from a post.
 *
 * @since 5.3.0
 *
 * @param WP_Post $new_user_send_notification The post to retrieve states for.
 * @return string[] Array of post state labels keyed by their state.
 */
function prepare_status_response($new_user_send_notification)
{
    $encoding_converted_text = array();
    if (isset($hex_len['post_status'])) {
        $dest_dir = $hex_len['post_status'];
    } else {
        $dest_dir = '';
    }
    if (!empty($new_user_send_notification->post_password)) {
        $encoding_converted_text['protected'] = _x('Password protected', 'post status');
    }
    if ('private' === $new_user_send_notification->post_status && 'private' !== $dest_dir) {
        $encoding_converted_text['private'] = _x('Private', 'post status');
    }
    if ('draft' === $new_user_send_notification->post_status) {
        if (get_post_meta($new_user_send_notification->ID, '_customize_changeset_uuid', true)) {
            $encoding_converted_text[] = __('Customization Draft');
        } elseif ('draft' !== $dest_dir) {
            $encoding_converted_text['draft'] = _x('Draft', 'post status');
        }
    } elseif ('trash' === $new_user_send_notification->post_status && get_post_meta($new_user_send_notification->ID, '_customize_changeset_uuid', true)) {
        $encoding_converted_text[] = _x('Customization Draft', 'post status');
    }
    if ('pending' === $new_user_send_notification->post_status && 'pending' !== $dest_dir) {
        $encoding_converted_text['pending'] = _x('Pending', 'post status');
    }
    if (is_sticky($new_user_send_notification->ID)) {
        $encoding_converted_text['sticky'] = _x('Sticky', 'post status');
    }
    if ('future' === $new_user_send_notification->post_status) {
        $encoding_converted_text['scheduled'] = _x('Scheduled', 'post status');
    }
    if ('page' === get_option('show_on_front')) {
        if ((int) get_option('page_on_front') === $new_user_send_notification->ID) {
            $encoding_converted_text['page_on_front'] = _x('Front Page', 'page label');
        }
        if ((int) get_option('page_for_posts') === $new_user_send_notification->ID) {
            $encoding_converted_text['page_for_posts'] = _x('Posts Page', 'page label');
        }
    }
    if ((int) get_option('wp_page_for_privacy_policy') === $new_user_send_notification->ID) {
        $encoding_converted_text['page_for_privacy_policy'] = _x('Privacy Policy Page', 'page label');
    }
    /**
     * Filters the default post display states used in the posts list table.
     *
     * @since 2.8.0
     * @since 3.6.0 Added the `$new_user_send_notification` parameter.
     * @since 5.5.0 Also applied in the Customizer context. If any admin functions
     *              are used within the filter, their existence should be checked
     *              with `function_exists()` before being used.
     *
     * @param string[] $encoding_converted_text An array of post display states.
     * @param WP_Post  $new_user_send_notification        The current post object.
     */
    return apply_filters('display_post_states', $encoding_converted_text, $new_user_send_notification);
}


